import { catalogue } from "./catalogue.ts";
import type { Cell, Row } from "./catalogueTypes.ts";
import { columns } from "./catalogueTypes.ts";

/**
 * The README table, generated from the catalogue. `bun run docs:gen` writes it between the markers; `bun run check:docs`
 * fails when the README differs, so the table cannot drift.
 */
export const beginMarker =
  "<!-- catalogue:begin (generated by `bun run docs:gen` from packages/core/src/catalogue.ts; do not edit) -->";

export const endMarker = "<!-- catalogue:end -->";

const cellText = (cell: Cell): string => `${cell.outcome} (${cell.verifiedBy})`;

const escapeCell = (text: string): string =>
  text.replaceAll("|", "\\|").replaceAll("\n", " ");

const sourceLinks = (row: Row): string =>
  row.sources.map((url, index) => `[${index + 1}](${url})`).join(" ");

export const renderCatalogueTable = (
  rows: readonly Row[] = catalogue
): string =>
  [
    "| Behaviour | Direct | Transaction-pooled (PgBouncer) | Hyperdrive | Sources |",
    "| --- | --- | --- | --- | --- |",
    ...rows.map(
      (row) =>
        `| ${escapeCell(row.behaviour)} | ${columns
          .map((column) => escapeCell(cellText(row[column])))
          .join(" | ")} | ${sourceLinks(row)} |`
    ),
  ].join("\n");

/** The README with the table between the markers replaced; throws when a marker is missing or out of order. */
export const withCatalogueTable = (
  readme: string,
  rows: readonly Row[] = catalogue
): string => {
  const begin = readme.indexOf(beginMarker);
  const end = readme.indexOf(endMarker);

  if (begin === -1 || end === -1 || end < begin) {
    throw new Error(
      "README.md must contain the catalogue begin and end markers, in that order"
    );
  }

  return `${readme.slice(0, begin + beginMarker.length)}\n\n${renderCatalogueTable(rows)}\n\n${readme.slice(end)}`;
};
